// integrate physics (semi-implicit / symplectic Euler, several substeps) -- real gravity
const G = 1.0;
const sub = Math.max(2, Math.min(14, Math.round(3 + P.speed * 3)));
const dt = 0.085;
const th1 = S.th1, th2 = S.th2, w1 = S.w1, w2 = S.w2;
for (let i = 0; i < N; i++) {
